package com.apeira.decor.block;

import net.minecraft.world.level.block.Block;
import net.minecraft.world.level.block.state.BlockBehaviour;
import net.minecraft.world.phys.shapes.Shapes;
import net.minecraft.world.phys.shapes.VoxelShape;

/** An oak chair, modelled on the server pack's saloon chair ({@code custom/furniture/western/saloon_chair}). */
public class OakChairBlock extends ApeiraChairBlock {
    /**
     * Legs, seat, armrests and backrest, facing north. Generated by {@code scripts/parse_blockbench_hitboxes.py} from
     * {@code assets/apeira/models/block/oak_chair.json}; the backrest reaches above the block, like a fence.
     */
    public static final VoxelShape SHAPE = Shapes.or(
            Block.box(1.3531, 0, 2.268, 3.3531, 8, 4.268),
            Block.box(12.6469, 0, 2.268, 14.6469, 8, 4.268),
            Block.box(1.3531, 0, 11.732, 3.3531, 8, 13.732),
            Block.box(12.6469, 0, 11.732, 14.6469, 8, 13.732),
            Block.box(1.354, 8, 1.5609, 15.354, 10, 14.5609),
            Block.box(1.354, 17, 3.5608, 3.354, 19, 13.5609),
            Block.box(13.354, 17, 3.5608, 15.354, 19, 13.5609),
            Block.box(1.354, 17, 13.5609, 15.354, 22, 15.5609));
    /** The top of the seat, in pixels. */
    public static final double SEAT_HEIGHT = 10;

    public OakChairBlock(BlockBehaviour.Properties properties) {
        super(properties, SHAPE, SEAT_HEIGHT);
    }
}
